<template><section class="warehouse-page" :class="{'warehouse-order-page':kind==='warehouse-order'}" v-loading="loading"><div class="toolbar" :class="{'has-business-filters':['warehouse-order','inventory'].includes(kind),'inventory-toolbar':kind==='inventory'}"><el-button v-if="['inventory','warehouse-order','process-batch'].includes(kind)&&actionPermission.hasAny(['metal:warehouse-order:query','metal:warehouse-order:add','metal:warehouse-order:receive','metal:warehouse-order:accept','metal:warehouse-order:handover'])" class="list-action list-action--primary warehouse-secondary-action" :icon="['inventory','warehouse-order'].includes(kind)?List:undefined" title="查看交接申请、核对称重并完成收发确认" @click="flowDialog?.open()">仓储交接待办</el-button><el-button v-if="['inventory','warehouse-order','process-batch'].includes(kind)&&allows('metal:warehouse-order:handover')" type="primary" class="list-action list-action--primary warehouse-primary-action" :icon="['inventory','warehouse-order'].includes(kind)?Switch:undefined" title="提交加工产出及全部余料，交由仓管员复称确认" @click="handoverDialog?.open()">加工产出交接</el-button><BusinessFilters v-if="kind==='warehouse-order'" kind="warehouse-order" :order-kind="tab" :allow-export="can('export')" :exporting="exporting" @apply="applyFilters" @export="exportRows"><template #actions><el-button v-if="can('add')" class="list-action list-action--create blue filter-add" :icon="Plus" @click="add">添加</el-button><el-button v-if="can('edit')" class="list-action list-action--edit orange" :icon="Edit" disabled title="已过账不能直接编辑，请查看后冲销">编辑</el-button><el-button v-if="can('remove')" class="list-action list-action--delete red" :icon="Delete" disabled title="已过账不能直接删除，请查看后冲销">删除</el-button></template></BusinessFilters><BusinessFilters v-if="kind==='inventory'" kind="inventory" :order-kind="tab" :allow-export="can('export')" :exporting="exporting" @apply="applyFilters" @export="exportRows"/><template v-if="kind!=='warehouse-order'"><el-button v-if="(kind==='inventory'?allows('metal:warehouse-order:add'):can('add'))&&kind!=='warning-record'&&kind!=='work-report'" class="list-action list-action--create blue" :icon="kind==='inventory'?Plus:undefined" :title="kind==='inventory'&&tab==='RAW'?'登记原材料入库，完成交接后入账':undefined" :disabled="kind==='warehouse'&&saving" @click="add">添加</el-button><el-button v-if="['warehouse','warning-rule','inventory'].includes(kind)&&(kind==='inventory'?can('adjust'):can('edit'))" class="list-action list-action--edit orange" :icon="kind==='inventory'?Edit:undefined" :title="kind==='inventory'?(selected.length===1?'填写净重差额与原因，增加或减少库存':'请先勾选一条库存记录'):undefined" :disabled="selected.length!==1||(kind==='warehouse'&&saving)" @click="edit(selected[0])">{{kind==='inventory'?'库存调整':'编辑'}}</el-button><el-button v-if="['warehouse','inventory','warning-rule','warning-record'].includes(kind)&&can('remove')&&!(kind==='inventory'&&tab==='RAW')" class="list-action list-action--delete red" :disabled="!selected.length||(kind==='warehouse'&&saving)" @click="remove(selected)">删除</el-button></template></div>
 <el-tabs type="card" v-if="tabs.length" v-model="tab" @tab-change="query.pageNum=1;load()"><el-tab-pane v-for="t in tabs" :key="t.value" :name="t.value" :label="t.label" :disabled="saving"/></el-tabs>
 <div v-if="kind==='inventory'&&adjustLoading" role="status">正在加载库存调整资料…<el-button class="list-action list-action--primary" link type="primary" @click="invalidateAdjustment">取消加载</el-button></div>
 <div v-if="kind==='warehouse'&&warehouseEditLoading" role="status">正在加载仓库资料… <el-button class="list-action list-action--primary" link type="primary" @click="cancelWarehouseEditor">取消加载</el-button></div>
