 <p v-if="refreshFailed" role="status">列表更新失败，当前数据可能过期。<el-button link @click="load">重试</el-button></p><el-table ref="listTable" :data="rows" row-key="id" border class="warehouse-table" :class="{'raw-inventory-table':kind==='inventory'&&tab==='RAW','warehouse-order-table':kind==='warehouse-order'}" @selection-change="selected=$event"><el-table-column v-if="showActions" type="selection" :width="kind==='warehouse-order'||kind==='inventory'&&tab==='RAW'?39:45"/><el-table-column v-for="c in columns" :key="c.key" :label="c.title" :prop="c.key" :min-width="c.width||85" align="center"><template #default="{row,$index}"><span v-if="kind==='process-batch'&&c.key==='id'">{{(query.pageNum-1)*query.pageSize+$index+1}}</span><span v-else-if="c.key==='status'&&['warehouse','warning-rule'].includes(kind)&&!can('edit')">{{row.status==='0'?'正常':'停用'}}</span><el-switch v-else-if="c.key==='status'&&['warehouse','warning-rule'].includes(kind)" :model-value="row.status" active-value="0" inactive-value="1" :disabled="!can('edit')||saving" @change="toggle(row,$event)"/><span v-else>{{display(row,c.key)}}</span></template></el-table-column><el-table-column v-if="showActions" label="操作" :min-width="kind==='inventory'&&tab==='RAW'?245:kind==='warehouse-order'?245:160" align="center"><template #default="{row}"><el-button v-if="can('query')" class="list-action list-action--primary list-action--row blue small" @click="view(row)">{{kind==='inventory'&&tab==='RAW'?'查看详情':kind==='warehouse-order'?'物料清单':kind==='warning-record'&&row.status==='PENDING'&&!row.sourceVoid?'去处理':'查看'}}</el-button><template v-if="['warehouse','warning-rule','inventory'].includes(kind)"><el-button v-if="kind==='inventory'?can('adjust'):can('edit')" class="list-action list-action--edit list-action--row orange small" :disabled="kind==='warehouse'&&saving" @click="edit(row)">{{kind==='inventory'?'库存调整':'编辑'}}</el-button></template><template v-if="kind==='warehouse-order'"><el-button v-if="can('edit')" class="list-action list-action--edit list-action--row orange small" disabled title="已过账不能直接编辑，请查看后冲销">编辑</el-button><el-button v-if="can('remove')" class="list-action list-action--delete list-action--row red small" disabled title="已过账不能直接删除，请查看后冲销">删除</el-button></template><el-button v-if="can('remove')&&kind!=='warehouse-order'&&!(kind==='inventory'&&tab==='RAW')" class="list-action list-action--delete list-action--row red small" :disabled="(kind==='warehouse'&&saving)||(kind==='warning-record'&&row.status==='PENDING'&&!row.sourceVoid)" @click="remove([row])">删除</el-button></template></el-table-column></el-table>
 <div v-if="failed" class="error"><el-button link @click="load">加载失败，点击重试</el-button></div><div class="pagination"><el-pagination v-model:current-page="query.pageNum" v-model:page-size="query.pageSize" :total="total" :page-sizes="[16,32,64]" layout="total, sizes, prev, pager, next, jumper" @current-change="load" @size-change="query.pageNum=1;load()"/></div>
 <InventoryOriginDialog ref="originDialog" @saved="originSaved"/><WarehouseFlowDialog ref="flowDialog" @saved="load"/><WarehouseHandoverDialog ref="handoverDialog" @saved="handoverSaved"/><AcidWashDialog ref="acidWash" @saved="load" @busy-change="saving=$event"/><BatchReturnConfirmationDialog @next-step="orderForm?.openNextStep($event)" ref="returnConfirmation" @saved="completionSaved" @busy-change="saving=$event"/><WarehouseOrderForm ref="orderForm" @handover="handoverDialog?.open($event||undefined)" @flow-created="flowDialog?.open($event)" @complete-batch="openCompletion" @saved="load" @busy-change="saving=$event"/><BatchForm ref="batchForm" @saved="load"/>
 <el-dialog class="warehouse-edit-dialog" :close-on-press-escape="!saving" :show-close="!saving" v-model="formVisible" :title="form.id?'编辑'+title:'添加'+title" width="min(620px,94vw)" :close-on-click-modal="false"><el-form ref="editForm" :model="form" :rules="editRules" scroll-to-error label-width="140px" label-position="left" :disabled="saving"><template v-if="kind!=='inventory'"><el-form-item label="所属工厂" :rules="[requiredRule('所属工厂',true,true),...([])]" prop="factoryId"><el-select v-model="form.factoryId" :disabled="!admin||!!form.id" fit-input-width @change="factoryChanged"><el-option v-for="o in factories" :key="o.id" :label="o.name" :value="o.id"/></el-select></el-form-item></template><template v-if="kind==='warehouse'"><el-form-item label="库房名称" prop="name" :rules="[requiredRule('库房名称',true,false),...([])]"><el-input v-model="form.name" maxlength="100"/></el-form-item><el-form-item label="显示顺序" prop="sortOrder"><el-input v-model.number="form.sortOrder" inputmode="numeric"/></el-form-item></template><template v-if="kind==='warning-rule'"><el-form-item label="产品" prop="productId"><el-select v-model="form.productId" :disabled="!!form.id" fit-input-width @change="productChanged"><el-option v-for="o in products" :key="o.id" :label="o.name" :value="o.id"/></el-select></el-form-item><el-form-item label="工序" prop="processId"><el-select v-model="form.processId" :disabled="!!form.id" fit-input-width><el-option v-for="o in processes" :key="o.id" :label="o.name" :value="o.id"/></el-select></el-form-item><el-form-item label="允许超差(g)" prop="tolerance"><BusinessDecimalInput v-model="form.tolerance" inputmode="decimal"/></el-form-item></template><el-form-item label="状态"><el-switch v-model="form.status" active-value="0" inactive-value="1"/></el-form-item></el-form><template #footer><el-button :disabled="saving" @click="formVisible=false">取消</el-button><el-button v-if="kind==='inventory'&&inventoryMode==='adjust'?can('adjust'):can(form.id?'edit':'add')" type="primary" :loading="saving" @click="kind==='inventory'&&inventoryMode==='adjust'?saveAdjustment():save()" :disabled="kind==='inventory'&&inventoryMode==='info'&&isReferenced(form)">确认</el-button></template></el-dialog>
 <el-dialog v-model="detailVisible" :close-on-click-modal="!saving" :close-on-press-escape="!saving" :show-close="!saving" :title="kind==='work-report'?'查看报工':title+'详情'" :width="kind==='inventory'&&detail?.category==='RAW'?'min(1160px,94vw)':'min(900px,94vw)'" class="warehouse-dialog"><template v-if="detail"><LossRateBasis v-if="['work-report','warning-record'].includes(kind)" :basis="detail.lossRateBasis" :weight="detail.lossRateDenominatorWeight??detail.netInputWeight"/><section v-if="kind==='warehouse-order'&&detail.type==='RAW_IN'" class="receipt-customers"><div v-for="(line,index) in detail.lines??[]" :key="line.id"><h4>第{{index+1}}条原料客户资料</h4><CustomerSnapshot :snapshot="line.customerSnapshot" :factory-owned="line.materialOwnership==='FACTORY'"/></div></section><div class="detail-info"><div v-for="c in detailFields" :key="c.key"><span class="detail-label">{{c.title}}：</span><span class="detail-value">{{display(detail,c.key)}}</span></div></div><section v-if="kind==='inventory'&&['RAW','SEMI'].includes(detail.category)"><p>粉料来源：{{powderOriginNames[detail.powderOrigin]||'来源待核对'}}；酸洗资格：{{washingStatusNames[detail.washingStatus]||'待核对'}}<template v-if="detail.category==='SEMI'">；融定资格：{{detail.smeltingStatus==='PASSED'?'融定合格':'待核对'}}</template></p><el-button v-if="allows('metal:inventory:verify-origin')" type="primary" @click="originDialog?.open(detail)">来源资格核对</el-button></section><el-button v-if="kind==='inventory'&&detail.originAcidWashId&&actionPermission.hasAny(['metal:warehouse-order:add','metal:warehouse-order:query'])" type="primary" @click="acidWash?.open(String(detail.factoryId),String(detail.originAcidWashId))">查看历史酸洗来源</el-button><p v-if="kind==='inventory'&&detail.recoveryWorkOrderNo">加工余料来源：{{detail.recoveryWorkOrderNo}} / {{detail.recoveryProcessName}} / {{detail.recoveryBatchNo}}；来源批次{{detail.recoveryBatchStatus==='SETTLED'?'已结算，可供同厂同客户生产领用':'未结算或已冲销，暂不可领用'}}。</p><p v-if="kind==='inventory'&&detail.category==='RAW'" class="raw-stock-total" role="status">剩余总量：{{decimalText(detail.netWeight)}} g</p><p v-if="kind==='inventory'&&detail.category==='RAW'&&!detail.customerId">原单位名称：{{detail.organization||'—'}}</p><p v-if="kind==='inventory'">账面净重：{{decimalText(detail.bookWeight??detail.netWeight)}} g；待确认占用：{{decimalText(detail.reservedWeight??0)}} g；可领余额：{{decimalText(detail.availableWeight??detail.netWeight)}} g。生产资格仍需核对工艺路线及释放额度。</p><section v-if="kind==='inventory'&&detail.originWorkOrderId" class="inventory-origin-trace"><p>来源工单：<router-link v-if="allows('metal:work-order:query')" :to="{path:'/metal/work-order',query:{id:String(detail.originWorkOrderId)}}">{{detail.originWorkOrderNo}}</router-link><span v-else>{{detail.originWorkOrderNo}}</span>；来源工序：{{detail.sourceProcessName||'历史未记录'}}；来源批次：{{detail.originBatchNo||'历史未记录'}}</p><p>下游去向见流水中的关联工单；内部转序只追溯，不重复计新增投入。</p></section><p v-if="detail.warehouseFlowId">本单净重为已确认的实际值；原始计划称重及逐条差异见交接记录。</p><el-button v-if="detail.warehouseFlowId" type="primary" @click="flowDialog?.open(String(detail.warehouseFlowId))">查看交接、实领与复称</el-button><p v-if="kind==='inventory'&&detail.category!=='RAW'">实测净重：{{decimalText(detail.netWeight)}} g；<template v-if="detail.measurementMode==='WEIGHT'">参考件数：{{detail.referenceComplete===false?'未完整记录':detail.referenceQuantity??'未记录'}}</template><template v-else>数量：{{detail.quantity}} 件</template></p><p v-if="kind==='inventory'&&detail.category==='SEMI'">已释放未领：<template v-if="detail.measurementMode!=='WEIGHT'">{{detail.releasedQuantity??0}}件 / </template>{{decimalText(detail.releasedWeight??'0.000000')}}g；尚未释放：<template v-if="detail.measurementMode!=='WEIGHT'">{{detail.unreleasedQuantity??detail.quantity}}件 / </template>{{decimalText(detail.unreleasedWeight??detail.netWeight)}}g。还库不会自动释放。</p><p v-if="kind==='work-report'">按领用净重比例分摊；{{detail.voided?'报工已作废，拆分重量不展示':stateNames[detail.status]}}</p><section v-if="detail.relatedInboundOrders?.length"><p>同次入库其他单据</p><el-button v-for="o in detail.relatedInboundOrders" :key="o.id" link type="primary" @click="view({id:o.id})">{{o.warehouseName}} · {{o.orderNo}}</el-button></section><section v-if="detail.relatedOutboundOrders?.length"><p>同次出库其他单据</p><el-button v-for="o in detail.relatedOutboundOrders" :key="o.id" link type="primary" @click="view({id:o.id})">{{o.warehouseName}} — {{o.orderNo}}</el-button></section><template v-if="detail.lines"><template v-if="rawDetailLines.length"><h4 class="stock-detail-title">原材料明细</h4><el-table :data="rawDetailLines" border class="raw-order-detail"><el-table-column label="物料编码" prop="code"/><el-table-column label="单位名称" prop="organization"/><el-table-column label="品名/类别" prop="name"/><el-table-column label="规格型号" prop="specification"/><el-table-column label="毛重(g)" prop="grossWeight" :formatter="decimalColumn"/><el-table-column label="杂质(g)" prop="impurity" :formatter="decimalColumn"/><el-table-column label="净重(g)" prop="netWeight" :formatter="decimalColumn"/><el-table-column label="用途" prop="purpose"/><el-table-column label="备注" prop="remark"/></el-table></template><template v-for="group in productDetailGroups" :key="group.category"><template v-if="group.lines.length"><h4 class="stock-detail-title">{{group.title}}</h4><el-table :data="group.lines" border :class="group.category==='FINISHED'?'finished-order-detail':'semi-order-detail'"><el-table-column label="物料编码" prop="code"/><el-table-column label="单位名称" prop="organization"/><el-table-column label="收货单位" prop="receivingOrganization" :formatter="receivingOrganizationText"/><el-table-column label="批次号" prop="batchNo"/><el-table-column label="品名/类别" prop="name"/><el-table-column label="规格型号" prop="specification"/><el-table-column label="纯度(%)" prop="purity" :formatter="decimalColumn"/><el-table-column label="数量(件)" :formatter="(r:Row)=>display(r,'quantity')" prop="quantity"/><el-table-column label="实测净重(g)" prop="netWeight" :formatter="decimalColumn"/><el-table-column label="备注" prop="remark"/></el-table></template></template></template><el-table v-if="detail.materials" :data="detail.materials" border><el-table-column label="物料编码" prop="code"/><el-table-column label="物料名称" prop="name"/><el-table-column label="损耗重量(g)" prop="lossWeight" :formatter="decimalColumn"/><el-table-column v-if="detail.outputStage!=='RAW'&&detail.measurementMode!=='WEIGHT'" label="平均损耗(g)" prop="averageLoss" :formatter="decimalColumn"/></el-table><el-table v-if="detail.ledger" :data="detail.ledger" border class="stock-ledger-table"><el-table-column label="来源单据" prop="orderNo"/><el-table-column label="关联工单" min-width="165"><template #default="{row}"><router-link v-if="row.workOrderId&&allows('metal:work-order:query')" :to="{path:'/metal/work-order',query:{id:String(row.workOrderId)}}">{{row.workOrderNo}}</router-link><span v-else>{{row.workOrderNo||'—'}}</span></template></el-table-column><el-table-column v-if="detail.category==='RAW'" label="时间" prop="createTime" min-width="160" :formatter="dateTimeCell"/><el-table-column v-if="detail.category==='RAW'" label="业务类型" prop="type" :formatter="r=>orderTypeNames[r.type]||r.type"/><el-table-column v-if="detail.category==='RAW'" label="当时客户公司名称" prop="customerCompanySnapshot" min-width="180"/><el-table-column label="净重变化(g)" prop="deltaWeight" min-width="145" :formatter="decimalColumn"/><el-table-column v-if="detail.category!=='RAW'" label="数量变化" prop="deltaQuantity"/><el-table-column label="净重余额(g)" prop="balanceWeight" :formatter="decimalColumn"/><el-table-column v-if="detail.category!=='RAW'" label="数量余额" prop="balanceQuantity"/><el-table-column label="调整原因" class-name="adjustment-reason" min-width="240"><template #default="{row}">{{String(row.adjustmentReason??'').trim()?row.adjustmentReason:'—'}}</template></el-table-column></el-table><el-table v-if="detail.orders" :data="detail.orders" border><el-table-column label="单据编号" prop="orderNo"/><el-table-column label="类型"><template #default="{row}">{{orderTypeNames[row.type]}}</template></el-table-column><el-table-column label="状态"><template #default="{row}">{{stateNames[row.status