function cancelWarehouseEditor(){if(saving.value)return;invalidateWarehouseEditor();clearWarehouseForm();factories.value=[]}
watch(formVisible,visible=>{if(kind==='warehouse'&&!visible&&!saving.value){++warehouseEditEpoch;warehouseEditContext=undefined;warehouseEditLoading.value=false;warehouseEditError.value=false}},{flush:'sync'})
onBeforeUnmount(()=>{warehouseDisposed=true;++warehouseEditEpoch;warehouseEditContext=undefined})
async function openWarehouseEditor(row?:Row){
 if(saving.value||warehouseDisposed||!sessionReady()||row&&!writeSession(rowsOwner))return
 invalidateWarehouseEditor();clearWarehouseForm();factories.value=[]
 const context:WarehouseEditContext={epoch:++warehouseEditEpoch,identity:listIdentity(),mode:row?'edit':'add',targetId:row?String(row.id):''}
 warehouseEditContext=context;warehouseEditLoading.value=true
 retryWarehouseEditor=()=>{void openWarehouseEditor(context.mode==='edit'?{id:context.targetId}:undefined)}
 try{
  const [response,options]=await Promise.all([
   context.mode==='edit'?warehouseDetail('warehouse',context.targetId,!can('query'),()=>warehouseContextValid(context)):Promise.resolve({data:{requestId:createUUID(),factoryId:'',name:'',sortOrder:0,status:'0'} as Row}),
   warehouseOptions('factories',undefined,undefined,()=>warehouseContextValid(context))
  ])
  if(!warehouseContextValid(context))return
  const draft=JSON.parse(JSON.stringify(response.data)) as Row
  if(context.mode==='edit'&&String(draft.id)!==context.targetId)throw new Error('仓库资料与选择对象不一致')
  if(context.mode==='add'&&!admin.value)draft.factoryId=options.data[0]?.id
  clearWarehouseForm();Object.assign(form,draft);factories.value=options.data;formVisible.value=true
 }catch{if(warehouseContextValid(context)){clearWarehouseForm();factories.value=[];warehouseEditError.value=true}}
 finally{if(warehouseContextValid(context))warehouseEditLoading.value=false}
}
async function saveWarehouseEditor(){
 const context=warehouseEditContext
 if(saving.value||warehouseEditLoading.value||!formVisible.value||!context||!warehouseContextValid(context))return
 if(!await editForm.value?.validate().catch(()=>false)||!warehouseContextValid(context))return
 if(!form.factoryId||!form.name?.trim()||!Number.isInteger(form.sortOrder)||form.sortOrder<0){ElMessage.error('请填写库房名称及非负整数顺序');return}
 if(context.mode==='edit'&&(String(form.id)!==context.targetId||form.version==null)){ElMessage.error('编辑对象已失效，请重新加载');return}
 if(context.mode==='add'&&form.id){ElMessage.error('新增对象已失效，请重新打开');return}
 const own=startWrite(context.identity);if(!own)return;const valid=()=>own()&&warehouseContextValid(context),payload=JSON.parse(JSON.stringify(form)) as Row
 try{await warehouseSave('warehouse',payload,valid);if(!valid())return;invalidateWarehouseEditor();clearWarehouseForm();ElMessage.success('保存成功');await load()}
 catch(error){if(valid())applyFieldErrors(editForm.value,error)}finally{if(own())saving.value=false}
}
async function toggleWarehouse(row:Row,value:unknown){
 const owner=rowsOwner,own=startWrite(owner);if(!own)return
 const payload=JSON.parse(JSON.stringify({...row,status:value})) as Row;invalidateWarehouseEditor()
 try{await warehouseSave('warehouse',payload,own);if(own())await load()}catch{}finally{if(own())saving.value=false}
}
async function archiveWarehouses(targets:Row[]){
 if(!targets.length)return;const owner=rowsOwner,own=startWrite(owner);if(!own)return
 const ids=targets.map(row=>String(row.id));invalidateWarehouseEditor()
 try{try{await ElMessageBox.confirm('确认归档选中的'+ids.length+'条记录？','删除确认')}catch{return}if(!own())return;await warehouseRemove('warehouse',ids,own);if(!own())return;ElMessage.success('归档成功');await load()}catch{}finally{if(own())saving.value=false}
}

function isReferenced(row?:Row){return !!row&&[true,1,'1'].includes(row.businessReferenced)}
async function edit(row:Row){if(kind==='warehouse'){await openWarehouseEditor(row);return}if(!writeSession(rowsOwner))return;if(kind==='inventory'&&row.ownershipStatus==='REVIEW'){ElMessage.warning('该库存来源待核对，暂不能调整');return}if(kind==='inventory'){await openAdjustment(row);return}const epoch=++formEpoch,owner=rowsOwner;formOwner=owner;const valid=()=>epoch===formEpoch&&writeSession(owner);const response=await warehouseDetail(kind,row.id,!can('query'),valid);if(!valid())return;const r=response.data;Object.keys(form).forEach(k=>delete form[k]);Object.assign(form,r);const options=await warehouseOptions('factories',undefined,undefined,valid);if(!valid())return;factories.value=options.data;if(kind==='warning-rule'){const data=await Promise.all([warehouseOptions('products',form.factoryId,undefined,valid),warehouseOptions('processes',form.factoryId,form.productId,valid)]);if(!valid())return;[products.value,processes.value]=data.map(r=>r.data)}formVisible.value=true}
async function factoryChanged(){if(kind==='warning-rule'){const epoch=formEpoch,owner=formOwner,factory=form.factoryId,valid=()=>epoch===formEpoch&&writeSession(owner)&&factory===form.factoryId;form.productId='';form.processId='';const r=await warehouseOptions('products',factory,undefined,valid);if(valid()){products.value=r.data;processes.value=[]}}}
async function productChanged(){if(kind==='warning-rule'){const epoch=formEpoch,owner=formOwner,factory=form.factoryId,product=form.productId,valid=()=>epoch===formEpoch&&writeSession(owner)&&factory===form.factoryId&&product===form.productId;form.processId='';const r=await warehouseOptions('processes',factory,product,valid);if(valid())processes.value=r.data}}
async function save(){if(kind==='warehouse'){await saveWarehouseEditor();return}const epoch=formEpoch,owner=formOwner,validForm=()=>epoch===formEpoch&&writeSession(owner)&&formVisible.value;if(saving.value||!validForm()||!await editForm.value?.validate().catch(()=>false)||!validForm())return;if(kind==='warning-rule'&&(!form.factoryId||!form.productId||!form.processId||!/^\d+(\.\d{1,6})?$/.test(String(form.tolerance)))){ElMessage.error('请选择产品工序并填写非负克数超差');return}const own=startWrite(owner);if(!own)return;const valid=()=>own()&&validForm(),payload=JSON.parse(JSON.stringify({...form,purity:form.purity||null}));try{await warehouseSave(kind,payload,valid);if(!valid())return;formVisible.value=false;ElMessage.success('保存成功');await load()}catch(error){if(valid())applyFieldErrors(editForm.value,error)}finally{if(own())saving.value=false}}
async function toggle(row:Row,value:any){if(kind==='warehouse'){await toggleWarehouse(row,value);return}const own=startWrite(rowsOwner);if(!own)return;try{await warehouseSave(kind,{...row,status:value},own);if(own())await load()}finally{if(own())saving.value=false}}
async function remove(targets:Row[]){if(kind==='warehouse'){await archiveWarehouses(targets);return}const own=startWrite(rowsOwner);if(!own)return;try{try{await ElMessageBox.confirm('确认归档选中的'+targets.length+'条记录？','删除确认')}catch{return}if(!own())return;await warehouseRemove(kind,targets.map(r=>r.id),own);if(!own())return;ElMessage.success('归档成功');await load()}finally{if(own())saving.value=false}}

let detailEpoch=0
async function view(row:Row){if(saving.value||!sessionReady())return;const current=++detailEpoch,owner=listIdentity();detailOwner=owner;const valid=()=>current===detailEpoch&&writeSession(owner);detail.value=undefined;detailVisible.value=false;const response=await warehouseDetail(kind,row.id,false,valid);if(!valid())return;detail.value=response.data;reason.value='';completedQuantityInput.value=undefined;completedQuantity.value=detail.value.plannedQuantity||1;detailVisible.value=true}

const reverseVisible=ref(false),reverseBusy=ref(false),reverseReason=ref(''),reverseError=ref(''),reverseNeedsReload=ref(false),reverseTarget=ref<Row>()
let reverseEpoch=0,reverseDisposed=false
function invalidateReverse(){++reverseEpoch;reverseVisible.value=false;reverseTarget.value=undefined;reverseBusy.value=false;reverseReason.value='';reverseError.value='';reverseNeedsReload.value=false}
function cancelReverse(){if(!reverseBusy.value)invalidateReverse()}
function isStandaloneRecovery(row:Row|undefined){return row?.batchStatus==='OPEN'&&(row.completionPolicy==='SINGLE_OUTPUT_RETURN'&&['SEMI_IN','FINISHED_IN'].includes(row.type)||row.type==='PROCESS_RAW_RETURN'&&row.completionPolicy!=='SINGLE_OUTPUT_RETURN')}
function reverse(){if(!writeSession(detailOwner)||saving.value||reverseDisposed||!detailVisible.value||!detail.value)return;invalidateReverse();reverseTarget.value=JSON.parse(JSON.stringify(detail.value));reverseVisible.value=true}
async function confirmReverse(){
 if(reverseBusy.value||!reverseVisible.value||reverseNeedsReload.value||!reverseTarget.value)return
 const epoch=reverseEpoch,owner=detailOwner,target={...reverseTarget.value},reason=reverseReason.value.trim()
 const valid=()=>!reverseDisposed&&writeSession(owner)&&owner===detailOwner&&epoch===reverseEpoch&&reverseVisible.value&&detailVisible.value&&String(detail.value?.id)===String(target.id)
 if(!valid()){invalidateReverse();return}
 if(!reason||reason.length>500){reverseError.value=!reason?'请填写原因':'原因最多500字';return}
 const own=startWrite(owner);if(!own)return;reverseBusy.value=true;reverseError.value=''
 const wholeBatch=target.batchId&&!isStandaloneRecovery(target);
 try{await warehouseAction(wholeBatch?'process-batch':kind,wholeBatch?target.batchId:target.id,'reverse',{version:wholeBatch?target.batchVersion:target.version,reason},valid);if(!valid())return;invalidateReverse();detailVisible.value=false;await load();if(own())ElMessage.success('冲销成功')}
 catch(error:any){if(!valid())return;reverseNeedsReload.value=/版本|已被修改|已修改|刷新/.test(String(error?.message??error));reverseError.value=reverseNeedsReload.value?'记录已变化，请关闭并重新加载':'冲销失败，原因已保留，请重试'}
 finally{if(own()){saving.value=false;if(epoch===reverseEpoch)reverseBusy.value=false}}
}
watch(reverseVisible,open=>{if(!open&&!reverseBusy.value)invalidateReverse()},{flush:'sync'})
watch(detailVisible,open=>{if(!open)invalidateReverse()},{flush:'sync'})
onBeforeRouteLeave(()=>{invalidateReverse()})
onBeforeRouteUpdate(()=>{invalidateReverse()})
onBeforeUnmount(()=>{reverseDisposed=true;invalidateReverse()})

function allows(permission:string){return actionPermission.has(permission)}
async function settleBoundBatch(){if(saving.value||!writeSession(detailOwner))return;if(completedQuantityError.value){ElMessage.error(completedQuantityError.value);return}if(!detail.value||!Number.isInteger(Number(completedQuantity.value))||completedQuantity.value<1){ElMessage.error('请填写正整数完成数量');return}const target={...detail.value},epoch=detailEpoch,own=startWrite(detailOwner);if(!own)return;const valid=()=>own()&&epoch===detailEpoch&&detailVisible.value;try{await warehouseAction('process-batch',target.batchId,'settle',{version:target.batchVersion,completedQuantity:Number(completedQuantity.value)},valid);if(!valid())return;detailVisible.value=false;await load();if(own())ElMessage.success('已结算并生成报工')}finally{if(own())saving.value=false}}
async function settle(){if(saving.value||!writeSession(detailOwner))return;if(completedQuantityError.value){ElMessage.error(completedQuantityError.value);return}if(!detail.value)return;const target={...detail.value},epoch=detailEpoch,own=startWrite(detailOwner);if(!own)return;const valid=()=>own()&&epoch===detailEpoch&&detailVisible.value;try{await warehouseAction(kind,target.id,'settle',{version:target.version,completedQuantity:Number(completedQuantity.value)},valid);if(!valid())return;detailVisible.value=false;await load();if(own())ElMessage.success('结算成功')}finally{if(own())saving.value=false}}
async function handle(){if(saving.value||!detail.value||!writeSession(detailOwner))return;if(!reason.value.trim()){ElMessage.error('请填写处理结果');return}const target={...detail.value},payload={version:detail.value.version,reason:reason.value},epoch=detailEpoch,own=startWrite(detailOwner);if(!own)return;const valid=()=>own()&&epoch===detailEpoch&&detailVisible.value;try{await warehouseAction(kind,target.id,'handle',payload,valid);if(!valid())return;detailVisible.value=false;await load();if(own())ElMessage.success('处理成功')}finally{if(own())saving.value=false}}
async function openAdjustment(row?:Row){if(saving.value)return;const id=row?.id??detail.value?.id,owner=detailVisible.value&&String(detail.value?.id)===String(id)?detailOwner:rowsOwner;if(!id||!writeSession(owner))return;adjustOwner=owner;adjustQuantityInput.value=undefined;adjustForm.value?.clearValidate();adjustVisible.value=false;const epoch=++adjustmentEpoch,valid=()=>epoch===adjustmentEpoch&&writeSession(owner)&&owner===adjustOwner;adjustTarget.value=undefined;adjustPeople.value=[];adjustLoading.value=true;adjustNeedsReload.value=false;try{const response=await warehouseDetail('inventory',id,!can('query'),valid);if(!valid())return;const target={...response.data};if(target.ownershipStatus==='REVIEW')throw new Error('该库存来源待核对，暂不能调整');const people=await warehouseOptions('people',target.factoryId,undefined,valid);if(!valid())return;adjustTarget.value=target;adjustPeople.value=people.data;Object.assign(adjust,{requestId:createUUID(),version:target.version,operatorId:'',keeperId:'',deltaWeight:'0',deltaGrossWeight:'',deltaImpurity:'',deltaQuantity:0,referenceQuantity:null,reason:''});adjustVisible.value=true}catch{if(valid()){adjustTarget.value=undefined;adjustVisible.value=false;ElMessage.error('库存调整资料加载失败，请核对库存来源后重新打开')}}finally{if(valid())adjustLoading.value=false}}

watch(detailVisible,open=>{if(!open&&!saving.value&&!adjustVisible.value){adjustmentEpoch++;adjustTarget.value=undefined;adjustLoading.value=false}},{flush:'sync'})
watch(adjustVisible,open=>{if(!open){adjustmentEpoch++;adjustTarget.value=undefined;adjustLoading.value=false}},{flush:'sync'})
const hasComponents=computed(()=>adjustTarget.value?.category==='RAW'&&(String(adjust.deltaGrossWeight??'').trim()!==''||String(adjust.deltaImpurity??'').trim()!==''))
const componentError=computed(()=>hasComponents.value&&adjustmentNet(adjust.deltaGrossWeight,adjust.deltaImpurity)===null?'毛重差额、杂质差额须同时填写合法数字，最多14位整数、6位小数':'')
watch(()=>[adjust.deltaGrossWeight,adjust.deltaImpurity],()=>{if(hasComponents.value){const value=adjustmentNet(adjust.deltaGrossWeight,adjust.deltaImpurity);if(value!==null)adjust.deltaWeight=value}})
async function saveAdjustment(){if(saving.value||adjustLoading.value||!adjustTarget.value||adjustNeedsReload.value||!writeSession(adjustOwner))return;const validationRound=adjustmentEpoch,owner=adjustOwner,validDraft=()=>validationRound===adjustmentEpoch&&writeSession(owner)&&owner===adjustOwner&&adjustVisible.value;if(!await adjustForm.value?.validate().catch(()=>false)||!validDraft())return;adjust.deltaQuantity=Number(adjust.deltaQuantity);if(adjustTarget.value.measurementMode==='WEIGHT')adjust.deltaQuantity=0;if(componentError.value){ElMessage.error(componentError.value);return}if(!adjust.operatorId||!adjust.keeperId||!adjust.reason?.trim()||!Number.isInteger(adjust.deltaQuantity)||!/^[-+]?\d+(\.\d{1,6})?$/.test(String(adjust.deltaWeight))){ElMessage.error('请填写合法调整差额及原因');return}const target={...adjustTarget.value},payload={...adjust};payload.referenceQuantity=payload.referenceQuantity==null||payload.referenceQuantity===''?null:Number(payload.referenceQuantity);delete payload.deltaGrossWeight;delete payload.deltaImpurity;if(hasComponents.value){payload.deltaGrossWeight=String(adjust.deltaGrossWeight).trim();payload.deltaImpurity=String(adjust.deltaImpurity).trim();payload.deltaWeight=adjustmentNet(payload.deltaGrossWeight,payload.deltaImpurity)!}const own=startWrite(owner);if(!own)return;const valid=()=>own()&&validDraft();try{await warehouseAction('inventory',target.id,'adjust',payload,valid);if(!valid())return;adjustVisible.value=false;detailVisible.value=false;formVisible.value=false;await load();if(own())ElMessage.success('调整已登记')}catch(error:any){if(!valid())return;applyFieldErrors(adjustForm.value,error);if(/版本|已被修改|已修改|刷新/.test(String(error?.message??error))){adjustNeedsReload.value=true;ElMessage.warning('库存已变更，请重新加载后确认差额')}}finally{if(own())saving.value=false}}

const listBlocked=computed(()=>formVisible.value||detailVisible.value||adjustVisible.value||!!flowDialog.value?.isOpen||!!handoverDialog.value?.isOpen||!!orderForm.value?.isOpen||!!batchForm.value?.isOpen||!!originDialog.value?.isOpen||!!returnConfirmation.value?.isOpen||!!acidWash.value?.isOpen)
const {failed:refreshFailed}=useInventoryRefresh(context=>readList(true,context.isCurrent),listBlocked,{allowed:canReadList,reset:resetList},{paused:computed(()=>reading.value||saving.value||adjustLoading.value||warehouseEditLoading.value)})
onMounted(load)
</script>
